<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Ivy Dental - About New Section</title>

  <link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet">

  <style>
    * {
      box-sizing: border-box;
    }

    html, body {
      margin: 0;
      padding: 0;
      background: #f7f8f2;
      overflow-x: hidden;
    }

    /* Requested class name */
    .about_new_section {
      width: 100%;
      background: #f7f8f2;
      position: relative;
      overflow: hidden;
    }

    .about_new_section .about_new_section_wrapper {
      width: 100%;
      max-width: 100%;
      margin: 0 auto;
    }

    /* Exact visual layer */
    .about_new_section .about_new_section_image {
      display: block;
      width: 100%;
      height: auto;
      max-width: 100%;
    }

    /* Desktop / laptop */
    @media (min-width: 768px) {
      .about_new_section .about_new_section_image {
        width: 100%;
        height: auto;
      }
    }

    /* Mobile:
       Keep full design visible. Allow horizontal scroll instead of cropping. */
    @media (max-width: 767.98px) {
      .about_new_section {
        overflow-x: auto;
        -webkit-overflow-scrolling: touch;
      }

      .about_new_section .about_new_section_wrapper {
        min-width: 1600px;
      }

      .about_new_section .about_new_section_image {
        width: 1600px;
        max-width: none;
        height: auto;
      }
    }

    /* Hidden semantic content */
    .about_new_section .about_new_section_hidden {
      position: absolute !important;
      width: 1px !important;
      height: 1px !important;
      margin: -1px !important;
      padding: 0 !important;
      overflow: hidden !important;
      clip: rect(0, 0, 0, 0) !important;
      border: 0 !important;
      white-space: nowrap !important;
    }
  </style>
</head>
<body>

  <section class="about_new_section">
    <div class="container-fluid p-0">
      <div class="about_new_section_wrapper">
        <img
          class="about_new_section_image"
          src="data:image/png;base64,"
          alt="About Us section banner"
        >
        <div class="about_new_section_hidden">
          <p>WHO WE ARE</p>
          <h1>About Us</h1>
          <p>People | Care | Smiles | Always</p>
          <p>A Healthier Smile A Brighter You</p>
          <p>Trusted Dental Care For Brighter Tomorrows</p>
        </div>
      </div>
    </div>
  </section>

  <script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script>
</body>
</html>
